<?php
session_start();
require_once(__DIR__.'/../includes/auth/auth.php');
require_once(__DIR__.'/../includes/db/db.php');
require_once(__DIR__.'/../../utils/security/csrf/csrf.php');
$pdo=get_db();$userId=(int)$_SESSION['user_id'];$notice='';$error='';$noticeType='success';
$q=$pdo->prepare('SELECT id,full_name,username,email,phone,created_at FROM users WHERE id=? AND role="student"');$q->execute([$userId]);$user=$q->fetch(PDO::FETCH_ASSOC);if(!$user){http_response_code(404);exit('Student account not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $token=$_POST['csrf_token']??'';if(!is_string($token)||!CSRF::validateToken($token)){$error='Your session expired. Refresh and try again.';}
 elseif(($_POST['action']??'')==='profile'){$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');if($name===''||mb_strlen($name)>100||!preg_match('/^[A-Za-z0-9 _.-]{3,50}$/',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($phone)>20){$error='Check your name, username, email, and phone number.';}else{try{$q=$pdo->prepare('SELECT id FROM users WHERE (username=? OR email=?) AND id<>? LIMIT 1');$q->execute([$username,$email,$userId]);if($q->fetch()){$error='That username or email is already in use.';}else{$q=$pdo->prepare('UPDATE users SET full_name=?,username=?,email=?,phone=? WHERE id=? AND role="student"');$q->execute([$name,$username,$email,$phone,$userId]);$user['full_name']=$name;$user['username']=$username;$user['email']=$email;$user['phone']=$phone;$_SESSION['username']=$username;$notice='Profile details saved.';}}catch(PDOException $e){error_log('LMS profile update: '.$e->getMessage());$error='Unable to save your profile right now.';}}}
 elseif(($_POST['action']??'')==='password'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$q=$pdo->prepare('SELECT password FROM users WHERE id=?');$q->execute([$userId]);$account=$q->fetch(PDO::FETCH_ASSOC);if(!$account||!password_verify($current,$account['password'])){$error='Current password is incorrect.';}elseif(strlen($new)<8||!preg_match('/[a-z]/',$new)||!preg_match('/[A-Z]/',$new)||!preg_match('/[0-9]/',$new)||$new!==$confirm){$error='Use at least 8 characters with uppercase, lowercase, and a number; confirm it correctly.';}else{$q=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$userId]);$notice='Password updated.';}}
 elseif(($_POST['action']??'')==='preferences'){$theme=($_POST['theme']??'light')==='dark'?'dark':'light';$_SESSION['lms_preferences']=['theme'=>$theme,'email_updates'=>isset($_POST['email_updates'])];$_SESSION['lms_theme']=$theme;$notice='Preferences saved for this session.';}
}
$q=$pdo->prepare('SELECT invoice_number,final_amount,currency,status,created_at,paid_at FROM payments WHERE user_id=? ORDER BY created_at DESC LIMIT 20');$q->execute([$userId]);$payments=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT success,ip_address,attempt_time FROM login_attempts WHERE user_id=? ORDER BY attempt_time DESC LIMIT 5');$q->execute([$userId]);$signIns=$q->fetchAll(PDO::FETCH_ASSOC);$preferences=$_SESSION['lms_preferences']??['theme'=>'light','email_updates'=>true];
$pageTitle='Account settings';include(__DIR__.'/../includes/header/header.php');include(__DIR__.'/../includes/navbar/navbar.php');include(__DIR__.'/../includes/sidebar/sidebar.php');
?>
<main class="container py-4 lms-settings"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><span class="text-uppercase small fw-bold text-primary">LEARNER ACCOUNT</span><h1 class="h2 fw-bold mb-1">Settings</h1><p class="text-muted mb-0">Manage your account and review your learning payments.</p></div><span class="badge rounded-pill text-bg-light">Member since <?=htmlspecialchars(date('M Y',strtotime($user['created_at'])),ENT_QUOTES,'UTF-8')?></span></div><?php if($notice):?><div class="alert alert-<?=$noticeType?>" role="status"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error):?><div class="alert alert-danger" role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><div class="row g-4"><div class="col-xl-7"><section class="card border-0 shadow-sm mb-4"><div class="card-header bg-white border-0 p-4 pb-0"><h2 class="h5 fw-bold"><i class="bi bi-person-circle text-primary me-2"></i>Profile information</h2><p class="text-muted small">These details are stored on your student account.</p></div><div class="card-body p-4 pt-2"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="profile"><div class="col-md-6"><label class="form-label" for="fullName">Full name</label><input class="form-control" id="fullName" name="full_name" maxlength="100" value="<?=htmlspecialchars($user['full_name']??'',ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-6"><label class="form-label" for="username">Username</label><input class="form-control" id="username" name="username" minlength="3" maxlength="50" value="<?=htmlspecialchars($user['username'],ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-6"><label class="form-label" for="email">Email address</label><input class="form-control" id="email" type="email" name="email" maxlength="100" value="<?=htmlspecialchars($user['email'],ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-6"><label class="form-label" for="phone">Phone</label><input class="form-control" id="phone" name="phone" maxlength="20" value="<?=htmlspecialchars($user['phone']??'',ENT_QUOTES,'UTF-8')?>"></div><div class="col-12"><button class="btn btn-primary" type="submit"><i class="bi bi-check2-circle me-1"></i>Save profile</button></div></form></div></section><section class="card border-0 shadow-sm"><div class="card-header bg-white border-0 p-4 pb-0"><h2 class="h5 fw-bold"><i class="bi bi-shield-lock text-primary me-2"></i>Password and security</h2><p class="text-muted small">Change your password and review recent sign-ins.</p></div><div class="card-body p-4 pt-2"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="password"><div class="col-12"><label class="form-label" for="currentPassword">Current password</label><input class="form-control" id="currentPassword" name="current_password" type="password" autocomplete="current-password" required></div><div class="col-md-6"><label class="form-label" for="newPassword">New password</label><input class="form-control" id="newPassword" name="new_password" type="password" minlength="8" autocomplete="new-password" required></div><div class="col-md-6"><label class="form-label" for="confirmPassword">Confirm new password</label><input class="form-control" id="confirmPassword" name="confirm_password" type="password" minlength="8" autocomplete="new-password" required></div><div class="col-12"><button class="btn btn-outline-primary" type="submit">Update password</button></div></form><hr class="my-4"><h3 class="h6 fw-bold">Recent sign-ins</h3><?php if(!$signIns):?><p class="small text-muted mb-0">No sign-in records are available for this account.</p><?php else:?><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Result</th><th>IP address</th><th>Time</th></tr></thead><tbody><?php foreach($signIns as $entry):?><tr><td><span class="badge text-bg-<?=$entry['success']?'success':'secondary'?>"><?=$entry['success']?'Successful':'Unsuccessful'?></span></td><td><?=htmlspecialchars($entry['ip_address']??'Unknown',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(date('M j, Y g:i A',strtotime($entry['attempt_time'])),ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></section></div><div class="col-xl-5"><section class="card border-0 shadow-sm mb-4"><div class="card-header bg-white border-0 p-4 pb-0"><h2 class="h5 fw-bold"><i class="bi bi-sliders text-primary me-2"></i>Preferences</h2><p class="text-muted small">Preferences apply to your current signed-in session.</p></div><div class="card-body p-4 pt-2"><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="preferences"><div class="mb-3"><label class="form-label" for="theme">Appearance</label><select class="form-select" id="theme" name="theme"><option value="light" <?=$preferences['theme']==='light'?'selected':''?>>Light</option><option value="dark" <?=$preferences['theme']==='dark'?'selected':''?>>Dark</option></select></div><div class="form-check form-switch mb-4"><input class="form-check-input" id="emailUpdates" type="checkbox" name="email_updates" <?=$preferences['email_updates']?'checked':''?>><label class="form-check-label" for="emailUpdates">Email updates</label></div><button class="btn btn-primary" type="submit">Save preferences</button></form></div></section><section class="card border-0 shadow-sm"><div class="card-header bg-white border-0 p-4 pb-0"><h2 class="h5 fw-bold"><i class="bi bi-receipt text-primary me-2"></i>Payment history</h2><p class="text-muted small">Transactions attached to your learner account.</p></div><div class="card-body p-4 pt-2"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Invoice</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php if(!$payments):?><tr><td colspan="3" class="text-center text-muted py-3">No payment records.</td></tr><?php endif;?><?php foreach($payments as $payment):?><tr><td><strong><?=htmlspecialchars($payment['invoice_number'],ENT_QUOTES,'UTF-8')?></strong><small class="d-block text-muted"><?=htmlspecialchars(date('M j, Y',strtotime($payment['created_at'])),ENT_QUOTES,'UTF-8')?></small></td><td><?=htmlspecialchars($payment['currency'],ENT_QUOTES,'UTF-8')?> <?=number_format((float)$payment['final_amount'],2)?></td><td><span class="badge text-bg-<?=$payment['status']==='paid'?'success':'light'?>"><?=htmlspecialchars(ucfirst($payment['status']),ENT_QUOTES,'UTF-8')?></span></td></tr><?php endforeach;?></tbody></table></div></div></section></div></div></main>
